export function BeforeAfterSlider({
  beforeLabel = "{{beforeLabel}}",
  afterLabel = "{{afterLabel}}",
  position = {{position}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ maxWidth: 360, font: "12px/1.4 system-ui, sans-serif", color: "#241430",
      "--pos": `${position}%`, "--accent": accent }}>
      <div style={{ position: "relative", overflow: "hidden", borderRadius: 12, border: "1px solid #24143022", aspectRatio: "5 / 3" }}>
        <div style={{ position: "absolute", inset: 0 }} aria-hidden="true">
          <svg viewBox="0 0 400 240" width="100%" height="100%" preserveAspectRatio="xMidYMid slice"><rect width="400" height="240" fill="#A8E6C1" /><circle cx="300" cy="80" r="50" fill="#FAF7F2" /></svg>
          <span style={{ position: "absolute", top: 8, left: 8, padding: "2px 8px", borderRadius: 6, background: "#241430cc", color: "#FAF7F2", fontWeight: 600 }}>{afterLabel}</span>
        </div>
        <div style={{ position: "absolute", inset: 0, clipPath: `inset(0 calc(100% - ${position}%) 0 0)` }} aria-hidden="true">
          <svg viewBox="0 0 400 240" width="100%" height="100%" preserveAspectRatio="xMidYMid slice"><rect width="400" height="240" fill="#241430" /><circle cx="300" cy="80" r="50" fill="#D9C8F0" /></svg>
          <span style={{ position: "absolute", top: 8, left: 8, padding: "2px 8px", borderRadius: 6, background: "#241430cc", color: "#FAF7F2", fontWeight: 600 }}>{beforeLabel}</span>
        </div>
        <div style={{ position: "absolute", top: 0, bottom: 0, left: `${position}%`, width: 3, background: accent, transform: "translateX(-50%)", pointerEvents: "none" }} />
      </div>
      {/* In production, wire this range's onChange to update `position` state so the divider is live-draggable. */}
      <input
        type="range"
        min={0}
        max={100}
        defaultValue={position}
        aria-label={`Comparison position between ${beforeLabel} and ${afterLabel}`}
        style={{ width: "100%", marginTop: 10, accentColor: accent }}
      />
    </div>
  );
}
